-- Processos da Empresa: tutoriais de uso do sistema (série SIS), um por área do sistema.
-- Publicados (versão 1). Migração apenas aditiva; não altera os processos existentes.
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-01', 'publicado', 1, '{"title": "Primeiro acesso e Minha conta", "area": "Sistema · Administração", "frequency": "Sob demanda", "objective": "Entrar no sistema pela primeira vez, trocar a senha provisória e manter o perfil (foto e senha) atualizado.", "erp_module": "Charão Gestão → Minha conta (foto/nome no menu)", "links": [{"kind": "link", "label": "Abrir Minha conta", "url": "https://charao-gestao.onrender.com/#/conta"}], "inputs": "E-mail cadastrado e senha provisória informados pelo administrador.", "outputs": "Senha pessoal definida; perfil com foto; acesso à tela de entrada (Meu painel ou Visão da empresa).", "rules": "A senha é pessoal e não deve ser compartilhada.\nNo primeiro acesso o sistema exige a troca da senha provisória.\nSe esquecer a senha, peça ao administrador uma nova senha provisória.", "indicators": [], "steps": [{"responsible": "Administrador", "activity": "Cadastra a pessoa e informa e-mail e senha provisória", "details": "Feito em **Gestão da Equipe → Cadastro da Equipe** (ver SIS-17).", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Entra com o e-mail e a senha provisória", "details": "- Acesse o endereço do sistema no celular ou no computador\n- No celular, use “Adicionar à tela inicial” para abrir como aplicativo", "control": false, "fail": null, "back_to": null}, {"responsible": "Sistema", "activity": "Pede a troca da senha provisória", "details": "A tela **Minha conta** abre sozinha com o aviso para definir a senha pessoal.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Define a senha pessoal e, se quiser, coloca a foto do perfil", "details": "- Toque na sua foto/iniciais no topo (celular) ou no seu nome no rodapé do menu (computador)\n- **Adicionar foto**: a imagem é recortada em quadrado automaticamente\n- A foto aparece no menu, organograma e listas", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Usa o menu para navegar", "details": "- **Computador**: menu lateral agrupado em Gestão de Obras, Gestão da Empresa, Gestão da Equipe e Administração\n- **Celular**: barra inferior com até 4 atalhos e o botão **Mais** com as demais seções\n- Só aparecem as seções liberadas para o seu usuário", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-02', 'publicado', 1, '{"title": "Meu painel e Visão da empresa", "area": "Sistema · Gestão de Obras", "frequency": "Diária", "objective": "Acompanhar diariamente as próprias tarefas (Meu painel) e o panorama geral da empresa (Visão da empresa).", "erp_module": "Charão Gestão → Meu painel / Visão da empresa", "links": [{"kind": "link", "label": "Abrir Meu painel", "url": "https://charao-gestao.onrender.com/#/painel"}], "inputs": "Tarefas cadastradas e atribuídas.", "outputs": "Prioridades do dia definidas; atrasos e conferências pendentes identificados.", "rules": "Comece o dia pelo Meu painel: atrasadas e as que vencem em 7 dias primeiro.\nA Visão da empresa só aparece para quem tem a seção liberada.", "indicators": ["Pontualidade (entregas no prazo)", "Tarefas atrasadas", "Tarefas em conferência"], "steps": [{"responsible": "Usuário", "activity": "Abre o Meu painel", "details": "- Indicadores: em aberto, atrasadas, vencem em 7 dias, em conferência, concluídas e pontualidade\n- Lista das próprias tarefas e check-lists por prioridade de prazo", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Trata primeiro as atrasadas e as que vencem hoje", "details": "Toque na tarefa para abrir, executar, registrar avanço ou reagendar (ver SIS-05 e SIS-06).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Acompanha as tarefas da equipe", "details": "No Meu painel do gestor aparece o bloco **Tarefas da equipe** e o que aguarda a sua conferência.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Consulta “Meu desempenho completo”", "details": "Dentro do Meu painel: histórico de entregas, pontualidade e evolução mês a mês.", "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria / Gestor", "activity": "Acompanha a Visão da empresa", "details": "- Panorama de todos os projetos acessíveis\n- Atrasos, conferências e desempenho por integrante\n- A tela de entrada (Meu painel ou Visão da empresa) é definida no cadastro de cada pessoa", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-03', 'publicado', 1, '{"title": "Cadastro de projetos e áreas internas", "area": "Sistema · Gestão de Obras", "frequency": "Sob demanda", "objective": "Cadastrar obras (projetos) e áreas internas da empresa, com classificações, equipe com acesso e calendário de dias úteis.", "erp_module": "Charão Gestão → Projetos", "links": [{"kind": "link", "label": "Abrir Projetos", "url": "https://charao-gestao.onrender.com/#/projetos"}], "inputs": "Dados da obra (nome, cliente, endereço, datas), tipo de projeto e modelo de classificação.", "outputs": "Projeto cadastrado (PRJ-000) ou área interna (INT-000) pronto para receber tarefas, registros e cronograma.", "rules": "Somente gestores, coordenadores e administradores cadastram e editam projetos.\nClassificações com tarefas não podem ser removidas: reclassifique as tarefas antes.\nTipos de projeto e modelos de classificação são definidos em Configurações (SIS-18).", "indicators": ["Tempo decorrido x prazo da obra", "Tarefas atrasadas por projeto"], "steps": [{"responsible": "Gestor / Coordenador", "activity": "Cria o projeto em Projetos → Novo projeto", "details": "- Escolha **Projeto (obra)** ou **Área interna da empresa**\n- O código é gerado automaticamente (PRJ-000 / INT-000)", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Preenche dados, tipo e datas", "details": "Cliente, endereço, responsável (líder), início e término previstos.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Define as classificações (Grupo / Local / Etapa)", "details": "Use um **modelo de classificação** (ex.: Fundação, Estrutura, Bloco A) ou cadastre as próprias. As tarefas serão organizadas por elas.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Libera o acesso das pessoas ao projeto", "details": "No cadastro de cada pessoa (Acesso e permissões): acesso total, projetos específicos ou só tarefas próprias.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Acompanha o projeto", "details": "- Tela do projeto: tarefas por classificação, check-lists, cronograma (Gantt), registros e equipe\n- Projetos concluídos ficam no filtro **Concluídos**", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-04', 'publicado', 1, '{"title": "Criar tarefas e subtarefas", "area": "Sistema · Gestão de Obras", "frequency": "Diária", "objective": "Registrar uma solicitação de trabalho com responsável, prazo, prioridade e o tipo de comprovação exigida na entrega.", "erp_module": "Charão Gestão → Tarefas → Nova tarefa (ou pelo projeto)", "links": [{"kind": "link", "label": "Criar nova tarefa", "url": "https://charao-gestao.onrender.com/#/tarefas/nova"}], "inputs": "O que precisa ser feito, projeto, responsável e prazo.", "outputs": "Tarefa com código (PRJ-000-00000) atribuída ao responsável e visível no Meu painel dele.", "rules": "O prazo é contado em dias úteis pelo calendário da obra e não conta as férias aprovadas do responsável.\nDescreva claramente o resultado esperado e anexe referências (fotos, PDF) quando ajudar.\nDefina a comprovação: nenhuma, somente foto, somente descrição ou foto + descrição.", "indicators": ["Tarefas sem responsável", "Tarefas sem prazo"], "steps": [{"responsible": "Solicitante", "activity": "Abre Tarefas → Nova tarefa", "details": "Também é possível criar a partir da tela do projeto ou do plano da semana.", "control": false, "fail": null, "back_to": null}, {"responsible": "Solicitante", "activity": "Escolhe o projeto/área e a classificação", "details": "O calendário de dias úteis usado no prazo é o da obra escolhida.", "control": false, "fail": null, "back_to": null}, {"responsible": "Solicitante", "activity": "Preenche título, descrição, responsável, início, prazo e prioridade", "details": "- **Prazo**: informe a data ou o número de dias úteis\n- **Prioridade**: baixa, média, alta ou urgente\n- **Sem responsável** só se for definir depois", "control": false, "fail": null, "back_to": null}, {"responsible": "Solicitante", "activity": "Define a comprovação exigida e anexa referências", "details": "- **Somente foto**: exige ao menos uma foto da execução\n- **Somente descrição**: exige texto da execução\n- **Foto + descrição**: exige os dois", "control": false, "fail": null, "back_to": null}, {"responsible": "Solicitante", "activity": "Salva; se necessário, cria subtarefas", "details": "- Na tarefa salva use **Nova subtarefa** para dividir o trabalho\n- **Duplicar** copia uma tarefa ou subtarefa\n- Para listas de verificação, use **Criar check-list** (SIS-07); para repetição, **Criar tarefa recorrente** (SIS-08)", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-05', 'publicado', 1, '{"title": "Executar e conferir tarefas", "area": "Sistema · Gestão de Obras", "frequency": "Diária", "objective": "Registrar a execução com a comprovação exigida e obter a conferência (aprovação) de quem solicitou ou do gestor.", "erp_module": "Charão Gestão → Tarefas → (tarefa)", "links": [{"kind": "link", "label": "Abrir Tarefas", "url": "https://charao-gestao.onrender.com/#/tarefas"}], "inputs": "Tarefa atribuída; fotos e descrição do serviço executado.", "outputs": "Tarefa concluída e conferida, com histórico, comprovação e data real de conclusão.", "rules": "Somente o responsável registra a execução (o líder registra pelo terceirizado sem acesso).\nO responsável não confere a própria entrega (exceto administrador e coordenador).\nDevolução sempre com o motivo, para o responsável ajustar.", "indicators": ["Entregas no prazo (%)", "Tempo médio em conferência", "Devoluções por tarefa"], "steps": [{"responsible": "Responsável da tarefa", "activity": "Abre a tarefa e inicia a execução", "details": "A tarefa passa de **Aberta** para **Em andamento**. Use **Avanço da tarefa** para informar o percentual quando for longa.", "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável da tarefa", "activity": "Registra a execução", "details": "- **Descrição da execução**: serviço realizado, materiais e conferências feitas\n- **Fotos ou PDF**: pela câmera ou galeria\n- **Observação**: pendências ou informações para o conferente", "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável da tarefa", "activity": "Envia para conferência", "details": "Botão **Enviar para conferência**. Se a entrega foi em outra data, informe a data real: quem confere autoriza ou define a data.", "control": false, "fail": null, "back_to": null}, {"responsible": "Quem confere (gestor / solicitante)", "activity": "Confere a entrega", "details": "- Analisa descrição e fotos\n- **Aprovar e concluir** ou **Devolver para ajustes** (com o motivo)", "control": true, "fail": "Devolvida → responsável ajusta e envia de novo", "back_to": 2}, {"responsible": "Sistema", "activity": "Conclui a tarefa e atualiza indicadores", "details": "Data de conclusão, pontualidade e histórico ficam registrados. Gestores podem **Concluir diretamente** quando não há conferência.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-06', 'publicado', 1, '{"title": "Reagendar prazo de tarefa", "area": "Sistema · Gestão de Obras", "frequency": "Sob demanda", "objective": "Alterar o prazo de uma tarefa com justificativa, mantendo o histórico de reagendamentos e o indicador de pontualidade confiável.", "erp_module": "Charão Gestão → Tarefas → (tarefa) → Reagendar prazo", "links": [{"kind": "link", "label": "Abrir Tarefas", "url": "https://charao-gestao.onrender.com/#/tarefas"}], "inputs": "Novo prazo e justificativa (lista padrão de justificativas).", "outputs": "Prazo atualizado com histórico: antes de vencer ou após vencer, motivo e quem alterou.", "rules": "Reagende antes de vencer sempre que possível: reagendamentos após o vencimento contam como atraso.\nTarefas com muitos reagendamentos viram “crônicas” (limite em Configurações).\nAs justificativas são cadastradas em Configurações.", "indicators": ["Reagendadas antes de vencer", "Repactuadas após vencer", "Tarefas crônicas"], "steps": [{"responsible": "Gestor / Coordenador", "activity": "Abre a tarefa e escolhe Reagendar prazo", "details": "Quem pode editar a tarefa (solicitante, gestor, administrador) reagenda.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Informa o novo prazo e a justificativa", "details": "Selecione a justificativa na lista e, se preciso, complemente com observação.", "control": false, "fail": null, "back_to": null}, {"responsible": "Sistema", "activity": "Registra o reagendamento e empurra as sucessoras", "details": "- Fica no histórico: “Reagendada antes de vencer” ou “com o prazo já vencido”\n- Tarefas dependentes (sucessoras) são ajustadas sem penalidade (ver SIS-09)", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Acompanha no filtro de tarefas", "details": "Em Tarefas use os filtros **Reagendadas**, **Repactuadas após vencer** e **Crônicas**.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-07', 'publicado', 1, '{"title": "Check-lists de verificação", "area": "Sistema · Gestão de Obras", "frequency": "Sob demanda", "objective": "Verificar itens em campo (Conforme / Não conforme / N/A) com fotos, observações e responsável por item.", "erp_module": "Charão Gestão → Tarefas → Nova tarefa → Criar check-list", "links": [{"kind": "link", "label": "Abrir Tarefas", "url": "https://charao-gestao.onrender.com/#/tarefas"}], "inputs": "Lista de itens a verificar (pode vir do modelo de especialidades da obra).", "outputs": "Check-list respondido, conferido e impresso (relatório do check-list ou lista de campo).", "rules": "Não conforme exige descrição e foto do problema; N/A exige justificativa.\nA regra de fotos vale para o check-list inteiro: obrigatória em todos os itens ou livre escolha.\nCom 100% de avanço o item continua pendente até ser marcado Conforme (ou N/A).", "indicators": ["% de itens conformes", "Não conformidades por check-list"], "steps": [{"responsible": "Solicitante", "activity": "Cria o check-list", "details": "- **Criar check-list** no lugar de tarefa\n- Cole os itens (um por linha) ou use a lista do modelo de especialidades\n- Agrupe por grupo/local e defina responsável e datas por item", "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável do item", "activity": "Verifica cada item em campo", "details": "- **Conforme**, **Não conforme** (com descrição e foto) ou **N/A** (com justificativa)\n- Fotos de entrada (antes) e de execução", "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável do item", "activity": "Corrige as não conformidades e atualiza o item", "details": "Após a correção, marque como Conforme com a foto da correção.", "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável da tarefa", "activity": "Envia o check-list para conferência", "details": "Quando todos os itens estão respondidos.", "control": false, "fail": null, "back_to": null}, {"responsible": "Quem confere (gestor / solicitante)", "activity": "Confere e conclui", "details": "Aprova ou devolve com o motivo.", "control": true, "fail": "Devolvido → itens corrigidos e reenviado", "back_to": 3}, {"responsible": "Usuário", "activity": "Imprime quando necessário", "details": "Relatório do check-list (com fotos e Gantt dos itens) ou **Lista de campo** (folha compacta para anotação).", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-08', 'publicado', 1, '{"title": "Tarefas recorrentes", "area": "Sistema · Gestão de Obras", "frequency": "Sob demanda", "objective": "Automatizar tarefas que se repetem (diárias, semanais, mensais…) para que sejam criadas sozinhas antes do prazo.", "erp_module": "Charão Gestão → Tarefas → Nova tarefa → Criar tarefa recorrente", "links": [{"kind": "link", "label": "Abrir Recorrências", "url": "https://charao-gestao.onrender.com/#/recorrencias"}], "inputs": "Modelo da tarefa (título, responsável, comprovação) e a regra de repetição.", "outputs": "Série de tarefas criadas automaticamente, cada uma uma tarefa normal com prazo e responsável.", "rules": "Cada ocorrência é criada alguns dias antes do prazo (antecedência definida na série).\nAlterar a série vale para as próximas ocorrências; as já criadas seguem normais.\nPara parar, use Encerrar recorrência (o histórico é mantido).", "indicators": ["Ocorrências entregues no prazo"], "steps": [{"responsible": "Solicitante", "activity": "Cria a tarefa recorrente", "details": "Preencha como uma tarefa normal e marque **Criar tarefa recorrente**.", "control": false, "fail": null, "back_to": null}, {"responsible": "Solicitante", "activity": "Define a regra de repetição", "details": "- Frequência (diária, semanal ou mensal) e dias\n- Prazo da 1ª ocorrência, antecedência de criação e duração\n- Término: sem fim, até uma data ou após N ocorrências", "control": false, "fail": null, "back_to": null}, {"responsible": "Sistema", "activity": "Cria cada ocorrência antes do prazo", "details": "A ocorrência aparece no Meu painel do responsável e segue o fluxo normal (SIS-05).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Acompanha e ajusta em Recorrências", "details": "Tela **Recorrências**: editar a série ou **Encerrar recorrência**.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-09', 'publicado', 1, '{"title": "Cronograma (Gantt) e dependências", "area": "Sistema · Gestão de Obras", "frequency": "Semanal", "objective": "Planejar a sequência das tarefas da obra no cronograma e ligar as que dependem umas das outras.", "erp_module": "Charão Gestão → Projetos → (projeto) → Cronograma (Gantt)", "links": [{"kind": "link", "label": "Abrir Projetos", "url": "https://charao-gestao.onrender.com/#/projetos"}], "inputs": "Tarefas do projeto com início e prazo.", "outputs": "Cronograma visual atualizado, com dependências e marcos (registros) do projeto.", "rules": "Dependência é sempre Término → Início (a sucessora só começa depois que a predecessora termina).\nQuando a predecessora atrasa, as sucessoras são empurradas sem penalizar o responsável delas.\nSó é possível ligar tarefas, subtarefas e itens de check-list do mesmo projeto.", "indicators": ["Impacto de atraso nas sucessoras"], "steps": [{"responsible": "Gestor / Coordenador", "activity": "Abre o cronograma do projeto", "details": "Barras por tarefa, com subtarefas (mostrar/ocultar) e marcos dos registros do projeto.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Liga as tarefas dependentes", "details": "Na tarefa: **Adicionar predecessora** (o que precisa terminar antes) ou **Adicionar sucessora** (o que só começa depois).", "control": false, "fail": null, "back_to": null}, {"responsible": "Sistema", "activity": "Mostra a situação “Aguardando” nas sucessoras", "details": "Enquanto a predecessora não termina, a sucessora aparece como aguardando.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Revisa semanalmente e reagenda o necessário", "details": "Ajustes de prazo seguem o SIS-06; a impressão do relatório pode incluir o Gantt.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-10', 'publicado', 1, '{"title": "Registros do projeto e atas de reunião", "area": "Sistema · Gestão de Obras", "frequency": "Sob demanda", "objective": "Registrar observações, definições, atas de reunião e pendências de cada obra, formando a linha do tempo e a história do projeto.", "erp_module": "Charão Gestão → Projetos → (projeto) → Registros", "links": [{"kind": "link", "label": "Abrir Projetos", "url": "https://charao-gestao.onrender.com/#/projetos"}], "inputs": "Informações da obra, reuniões, solicitações do cliente, ocorrências.", "outputs": "Linha do tempo do projeto; definições vigentes; tarefas geradas pelas pendências e demandas de ata; atas em PDF.", "rules": "Definição nova pode substituir uma anterior (a antiga fica no histórico como substituída).\nTipos que exigem aprovação ficam “Aguardando aprovação” até um gestor aprovar.\nOs tipos de registro e seus ícones são configurados em Configurações.", "indicators": ["Pendências em aberto", "Definições vigentes"], "steps": [{"responsible": "Usuário", "activity": "Abre Registros no projeto e escolhe o tipo", "details": "Nota, Decisão (definição), Reunião (ata) ou Pendência, conforme os tipos cadastrados.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Preenche o registro", "details": "- Data, origem, descrição e anexos\n- **Ata**: participantes, pauta e itens (Informação, Definição ou Demanda com responsável e prazo)\n- Opcional: vincular a tarefas existentes", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Aprova ou emite", "details": "Ao **emitir a ata**, as definições passam a valer e as demandas viram tarefas; pendências geram tarefa automaticamente.", "control": true, "fail": "Reprovado → registro volta para ajuste", "back_to": 2}, {"responsible": "Sistema", "activity": "Mostra os registros no Gantt e na História do projeto", "details": "Cada tipo tem seu ícone no cronograma; a **História do projeto** conta mês a mês o que aconteceu.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Imprime a ata ou a história", "details": "Ata em PDF pelo registro; História do projeto em Relatórios (SIS-11).", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-11', 'publicado', 1, '{"title": "Relatórios e impressões", "area": "Sistema · Gestão de Obras", "frequency": "Semanal/Mensal", "objective": "Emitir relatórios em PDF (A4) de projetos, pessoas, equipes e da empresa para acompanhamento e prestação de contas.", "erp_module": "Charão Gestão → Relatórios", "links": [{"kind": "link", "label": "Abrir Relatórios", "url": "https://charao-gestao.onrender.com/#/relatorios"}], "inputs": "Escopo (projeto, usuário, gestor/equipe ou empresa), período e nível de detalhe.", "outputs": "Documento A4 pronto para imprimir ou salvar em PDF.", "rules": "Os relatórios mostram apenas o que o seu usuário pode ver.\nPara enviar ao cliente, prefira o nível Detalhado; use Completo com fotos para comprovação.", "indicators": [], "steps": [{"responsible": "Usuário", "activity": "Escolhe o tipo de relatório", "details": "- **Projeto**: andamento consolidado da obra\n- **Usuário**: desempenho e tarefas de um responsável\n- **Gestor / equipe**: consolidado da equipe\n- **História do projeto**: narrativa cronológica", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Define período, nível e agrupamento", "details": "- Níveis: **Indicadores**, **Detalhado** ou **Completo com fotos**\n- Agrupar por status e prazo, dia, semana, mês ou classificação\n- Opções de Gantt (recolhido, sem subtarefas)", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Gera e confere a pré-visualização", "details": "O documento abre em folhas A4 na tela.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Imprime ou salva em PDF", "details": "Botão **Imprimir / Salvar PDF**. Também há relatórios direto da lista de Tarefas (Emitir relatório das tarefas).", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-12', 'publicado', 1, '{"title": "Contratos e medições", "area": "Sistema · Gestão da Empresa", "frequency": "Mensal", "objective": "Controlar contratos, planilha contratual, medições mensais (boletins) e o faturamento e recebimento.", "erp_module": "Charão Gestão → Gestão da Empresa → Contratos", "links": [{"kind": "link", "label": "Abrir Contratos", "url": "https://charao-gestao.onrender.com/#/contratos"}], "inputs": "Contrato assinado com itens (planilha contratual) e aditivos; quantidades executadas no mês.", "outputs": "Boletim de medição emitido (PDF); faturamento (NF) e recebimento registrados; indicadores de faturado x a receber.", "rules": "Acesso restrito: somente usuários com a liberação de Contratos.\nItem já medido não pode ser removido do contrato.\nUma medição emitida pode ser reaberta para correção (volta a rascunho).", "indicators": ["Medido x contratado", "Faturado no mês / no ano", "A receber"], "steps": [{"responsible": "Administrativo / Gestor", "activity": "Cadastra o contrato e a planilha contratual", "details": "Código automático (CT-000), cliente, vigência, itens com quantidades e preços; aditivos quando houver.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrativo / Gestor", "activity": "Cria a medição do mês", "details": "**Criar medição**: informe as quantidades executadas de cada item, descontos e acréscimos.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Confere e emite a medição", "details": "**Emitir medição** gera o boletim (PDF) para o cliente.", "control": true, "fail": "Erro encontrado → Reabrir medição e corrigir", "back_to": 2}, {"responsible": "Financeiro", "activity": "Registra o faturamento (NF)", "details": "**Registrar faturamento** com o número/data da nota.", "control": false, "fail": null, "back_to": null}, {"responsible": "Financeiro", "activity": "Registra o recebimento", "details": "**Registrar recebimento** quando o pagamento entra. É possível desfazer faturamento ou recebimento lançado por engano.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-13', 'publicado', 1, '{"title": "Tarefas financeiras (obrigações)", "area": "Sistema · Gestão da Empresa", "frequency": "Mensal", "objective": "Controlar as obrigações financeiras da empresa (impostos, folha, fornecedores, contas) como parcelas com prazo e responsável.", "erp_module": "Charão Gestão → Gestão da Empresa → Tarefas financeiras", "links": [{"kind": "link", "label": "Abrir Tarefas financeiras", "url": "https://charao-gestao.onrender.com/#/financeiro"}], "inputs": "Obrigação (categoria, valor, vencimento e periodicidade) e comprovantes de pagamento.", "outputs": "Parcelas pagas com valor e comprovante; análise de gastos x faturado.", "rules": "Acesso restrito: somente usuários com a liberação de Tarefas financeiras.\nCada parcela também é uma tarefa na área interna Financeiro, com responsável e prazo.\nPagamento lançado por engano pode ser desfeito.", "indicators": ["Parcelas atrasadas", "Pagas no mês", "Gastos x faturado"], "steps": [{"responsible": "Financeiro", "activity": "Cadastra a obrigação", "details": "**Nova obrigação**: categoria, descrição, valor, vencimento, periodicidade (única, mensal, bimestral, trimestral, semestral ou anual) e responsável.", "control": false, "fail": null, "back_to": null}, {"responsible": "Sistema", "activity": "Gera as parcelas e as tarefas", "details": "Cada parcela aparece no mês e no Meu painel do responsável.", "control": false, "fail": null, "back_to": null}, {"responsible": "Financeiro", "activity": "Paga e registra o pagamento", "details": "**Registrar pagamento** com o valor pago e o comprovante (foto ou PDF).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Acompanha o mês e a análise", "details": "- Visão do mês: atrasadas, vencem hoje, próximos 7 dias, pagas\n- **Análise financeira**: comparativo de gastos x faturado por período", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-14', 'publicado', 1, '{"title": "Processos da Empresa: criar, aprovar e publicar", "area": "Sistema · Gestão da Empresa", "frequency": "Sob demanda", "objective": "Documentar como cada atividade deve ser executada e manter o manual de processos atualizado, com aprovação do administrador.", "erp_module": "Charão Gestão → Gestão da Empresa → Processos da Empresa", "links": [{"kind": "link", "label": "Abrir Processos da Empresa", "url": "https://charao-gestao.onrender.com/#/processos"}], "inputs": "Conhecimento da atividade: responsáveis, etapas, pontos de controle, entradas, saídas e indicadores.", "outputs": "Processo publicado para todos; manual impresso; mapa mental das ligações entre processos.", "rules": "Todos leem os processos publicados.\nGestor e coordenador criam e editam, mas só o administrador aprova e publica (ou devolve com o motivo).\nPublicados não são apagados: são arquivados; cada publicação gera uma versão.", "indicators": ["Processos aguardando aprovação", "Processos sem responsável definido"], "steps": [{"responsible": "Gestor / Coordenador", "activity": "Cria ou edita o processo", "details": "- **Novo processo**: nome, área, frequência, objetivo, módulo no ERP e material de apoio\n- **Fluxo de etapas**: responsável, atividade, “como fazer” e pontos de controle (com a etapa de retorno)\n- Entradas, saídas, regras, indicadores e processos relacionados", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Envia para aprovação", "details": "**Salvar e enviar para aprovação** informando o que mudou. Até a aprovação, os leitores continuam vendo a versão anterior.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Revisa e aprova", "details": "**Aprovar e publicar** ou **Devolver** com o motivo.", "control": true, "fail": "Devolvido → ajustar e enviar de novo", "back_to": 1}, {"responsible": "Sistema", "activity": "Publica a nova versão para todos", "details": "A versão anterior fica no histórico; o mapa mental e o manual impresso são atualizados.", "control": false, "fail": null, "back_to": null}, {"responsible": "Usuário", "activity": "Consulta o manual", "details": "Mapa de processos por área, busca, **Mapa mental** e **Imprimir manual** (uma página por processo).", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-15', 'publicado', 1, '{"title": "Organograma", "area": "Sistema · Gestão da Equipe", "frequency": "Sob demanda", "objective": "Visualizar e manter a hierarquia da empresa (quem responde a quem), com função e responsabilidades de cada pessoa.", "erp_module": "Charão Gestão → Gestão da Equipe → Organograma", "links": [{"kind": "link", "label": "Abrir Organograma", "url": "https://charao-gestao.onrender.com/#/equipe/organograma"}], "inputs": "Pessoas cadastradas com gestor/líder definido.", "outputs": "Organograma atualizado, impresso em PDF quando necessário.", "rules": "Acesso pela seção Organograma e Férias.\nO gestor definido no organograma é quem acompanha as tarefas e aprova as férias da pessoa.\nNão é possível criar ciclos (alguém ser gestor do próprio gestor).", "indicators": ["Pessoas sem função ou responsabilidades", "Pessoas sem gestor"], "steps": [{"responsible": "Gestor / Administrador", "activity": "Abre o Organograma", "details": "Cada cartão mostra foto, nome, função, carga de tarefas e se está de férias.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Administrador", "activity": "Ajusta a hierarquia arrastando o cartão", "details": "Arraste a pessoa para o novo gestor; o sistema pede confirmação.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Administrador", "activity": "Completa função e responsabilidades", "details": "Pessoas sem função/responsabilidades aparecem destacadas: complete no Cadastro da Equipe (SIS-17).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Administrador", "activity": "Imprime o organograma", "details": "Botão de impressão gera o organograma em página paisagem.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-16', 'publicado', 1, '{"title": "Férias: solicitação e aprovação", "area": "Sistema · Gestão da Equipe", "frequency": "Sob demanda", "objective": "Solicitar, aprovar e controlar férias conforme as regras de períodos, reagendando as entregas que caem no período.", "erp_module": "Charão Gestão → Meu painel (minhas férias) / Gestão da Equipe → Férias", "links": [{"kind": "link", "label": "Abrir Férias", "url": "https://charao-gestao.onrender.com/#/equipe/ferias"}], "inputs": "Período desejado; admissão da pessoa (base dos períodos aquisitivos); tarefas com prazo no período.", "outputs": "Férias aprovadas; dias não contados nos prazos das tarefas; entregas reagendadas.", "rules": "Até 3 partes; uma delas com 14 dias ou mais; nenhuma com menos de 5 dias; total de até 30 dias.\nNão iniciar nos 2 dias que antecedem domingo ou feriado.\nSe houver entregas no período, é obrigatório propor novos prazos: eles só valem quando o gestor aprova.", "indicators": ["Períodos vencidos", "Pessoas de férias no mês"], "steps": [{"responsible": "Colaborador", "activity": "Solicita as férias pelo Meu painel", "details": "Informe início e quantidade de dias. O sistema confere as regras e mostra avisos.", "control": false, "fail": null, "back_to": null}, {"responsible": "Colaborador", "activity": "Propõe novos prazos para as entregas do período", "details": "O sistema lista as tarefas com prazo dentro das férias e sugere uma data após o retorno.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor da pessoa", "activity": "Analisa a solicitação e as propostas", "details": "Vê os reagendamentos propostos e eventuais novos conflitos.", "control": true, "fail": "Recusada → colaborador ajusta o período e solicita de novo", "back_to": 1}, {"responsible": "Sistema", "activity": "Aplica os novos prazos e bloqueia os dias de férias", "details": "Os prazos mudam com a justificativa “Férias do responsável”; os dias de férias não contam no prazo de novas tarefas.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Administrador", "activity": "Acompanha o mapa de férias", "details": "Em **Férias**: mapa do ano, saldos por período e aprovações pendentes.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-17', 'publicado', 1, '{"title": "Cadastro da Equipe e acesso ao sistema", "area": "Sistema · Gestão da Equipe", "frequency": "Sob demanda", "objective": "Cadastrar as pessoas da empresa (com ou sem acesso ao sistema), sua função e responsabilidades, e liberar acessos e seções.", "erp_module": "Charão Gestão → Gestão da Equipe → Cadastro da Equipe", "links": [{"kind": "link", "label": "Abrir Cadastro da Equipe", "url": "https://charao-gestao.onrender.com/#/equipe/cadastro"}], "inputs": "Dados da pessoa: nome, função, responsabilidades, setor, admissão, gestor; e-mail para quem terá acesso.", "outputs": "Pessoa cadastrada no organograma; acesso e permissões configurados.", "rules": "Função e responsabilidades são obrigatórias.\nPessoas sem acesso ao sistema também são cadastradas (aparecem no organograma e podem ser responsáveis acompanhadas pelo líder).\nAo mudar permissões, a pessoa precisa entrar novamente.", "indicators": ["Pessoas sem função/responsabilidades"], "steps": [{"responsible": "Administrador / Gestão da Equipe", "activity": "Cadastra a pessoa", "details": "**Cadastro da Equipe → Nova pessoa** (com ou sem acesso ao sistema): nome, função, responsabilidades, setor, data de admissão e gestor.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Libera o acesso (se a pessoa usará o sistema)", "details": "Em **Acesso e permissões**: e-mail, senha provisória, perfil (Administrador, Gestor, Coordenador, Colaborador) e terceirizado se for o caso.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Define escopo de projetos e seções liberadas", "details": "- Escopo: todos os projetos, projetos específicos ou só tarefas próprias\n- Seções: Gestão de Obras, Gestão da Empresa, Gestão da Equipe e Administração\n- Tela de entrada: Meu painel ou Visão da empresa", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Informa e-mail e senha provisória à pessoa", "details": "No primeiro acesso a pessoa troca a senha (SIS-01).", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Mantém o cadastro atualizado", "details": "Mudança de função, gestor, inativação de quem saiu (o histórico é preservado).", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-18', 'publicado', 1, '{"title": "Configurações gerais", "area": "Sistema · Administração", "frequency": "Sob demanda", "objective": "Manter os cadastros gerais que padronizam o sistema: tipos, modelos, calendário de trabalho e justificativas.", "erp_module": "Charão Gestão → Administração → Configurações", "links": [{"kind": "link", "label": "Abrir Configurações", "url": "https://charao-gestao.onrender.com/#/configuracoes"}], "inputs": "Padrões da empresa (feriados, tipos de projeto, classificações, especialidades, justificativas).", "outputs": "Cadastros gerais atualizados e usados em todo o sistema.", "rules": "Acesso: gestores e administradores (seção Configurações).\nItens em uso não são excluídos: inative-os.\nO calendário de trabalho define os dias úteis usados nos prazos.", "indicators": [], "steps": [{"responsible": "Gestor / Coordenador", "activity": "Calendário de trabalho", "details": "Dias da semana trabalhados e feriados: base do cálculo de prazos em dias úteis.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Tipos de projeto e modelos de classificação", "details": "Ex.: Residencial, Comercial; classificações por linha (Fundação, Estrutura, Bloco A).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Modelos de especialidades", "details": "Listas usadas nos check-lists (Pintura, Revestimento, Elétrica…).", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Justificativas de reagendamento e limite de tarefa crônica", "details": "Lista de motivos aceitos e quantos reagendamentos tornam a tarefa crônica.", "control": false, "fail": null, "back_to": null}, {"responsible": "Gestor / Coordenador", "activity": "Tipos de registro do projeto", "details": "Nome, comportamento (nota, decisão, reunião, pendência), ícone, cor e se exige aprovação.", "control": false, "fail": null, "back_to": null}], "related": []}', '2026-10-18 12:00:00');
INSERT OR IGNORE INTO processes (code, status, version, published, published_at) VALUES ('SIS-19', 'publicado', 1, '{"title": "Auditoria", "area": "Sistema · Administração", "frequency": "Mensal", "objective": "Consultar o registro das ações administrativas para garantir rastreabilidade e segurança.", "erp_module": "Charão Gestão → Administração → Auditoria", "links": [{"kind": "link", "label": "Abrir Auditoria", "url": "https://charao-gestao.onrender.com/#/auditoria"}], "inputs": "Ações realizadas no sistema (cadastros, permissões, publicações).", "outputs": "Rastreabilidade de quem fez o quê e quando.", "rules": "Acesso apenas para quem tem a seção Auditoria (padrão: administradores).\nOs registros não podem ser alterados nem apagados.", "indicators": ["Alterações de permissão no mês"], "steps": [{"responsible": "Administrador", "activity": "Abre a Auditoria", "details": "Lista das ações mais recentes: data, pessoa, ação e detalhes.", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Analisa as ações recentes", "details": "A lista mostra as últimas ações (ex.: mudanças de permissão, cadastros, publicação de processos).", "control": false, "fail": null, "back_to": null}, {"responsible": "Administrador", "activity": "Verifica ações fora do padrão", "details": "Acessos ou alterações inesperadas.", "control": true, "fail": "Ação indevida → corrigir o acesso/cadastro e orientar a pessoa", "back_to": null}], "related": []}', '2026-10-18 12:00:00');
