UPDATE processes SET published = json_set(published, '$.related', json_array((SELECT id FROM processes WHERE code = 'SIS-01'), (SELECT id FROM processes WHERE code = 'SIS-15'))) WHERE code = 'SIS-17';
UPDATE processes SET published = json_set(published, '$.related', json_array((SELECT id FROM processes WHERE code = 'SIS-03'), (SELECT id FROM processes WHERE code = 'SIS-06'), (SELECT id FROM processes WHERE code = 'SIS-10'))) WHERE code = 'SIS-18';
UPDATE processes SET published = json_set(published, '$.related', json_array((SELECT id FROM processes WHERE code = 'SIS-17'))) WHERE code = 'SIS-19';
INSERT INTO process_versions (process_id, version, content, note, published_at)
  SELECT id, 1, published, 'Tutorial de uso do sistema (carga inicial)', published_at FROM processes
  WHERE code LIKE 'SIS-%' AND NOT EXISTS (SELECT 1 FROM process_versions v WHERE v.process_id = processes.id);
